Pruebas con JUnit 5:

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.math.BigDecimal;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.junit.jupiter.params.provider.ValueSource;

class InstalmentSplitterTest {

    private final InstalmentSplitter splitter = new InstalmentSplitter();

    @Test
    void split_exactDivision_returnsEqualInstalments() {
        List<BigDecimal> result = splitter.split(new BigDecimal("1000.00"), 4);

        assertEquals(List.of(new BigDecimal("250.00"), new BigDecimal("250.00"),
                new BigDecimal("250.00"), new BigDecimal("250.00")), result);
    }

    @Test
    void split_divisionWithRemainder_putsRemainderInLastInstalment() {
        List<BigDecimal> result = splitter.split(new BigDecimal("1000.00"), 3);

        assertEquals(List.of(new BigDecimal("333.33"), new BigDecimal("333.33"),
                new BigDecimal("333.34")), result);
    }

    @Test
    void split_singleInstalment_returnsTotal() {
        List<BigDecimal> result = splitter.split(new BigDecimal("500.00"), 1);

        assertEquals(List.of(new BigDecimal("500.00")), result);
    }

    @ParameterizedTest
    @CsvSource({"1000.00,3", "0.05,12", "999.99,7", "12345.67,12"})
    void split_validInput_instalmentsAddUpToTotal(String total, int instalments) {
        BigDecimal expected = new BigDecimal(total);

        BigDecimal sum = splitter.split(expected, instalments).stream()
                .reduce(BigDecimal.ZERO, BigDecimal::add);

        assertEquals(0, expected.compareTo(sum));
    }

    @ParameterizedTest
    @ValueSource(ints = {0, -1, 13})
    void split_instalmentsOutOfRange_throwsIllegalArgumentException(int instalments) {
        assertThrows(IllegalArgumentException.class,
                () -> splitter.split(new BigDecimal("100.00"), instalments));
    }

    @ParameterizedTest
    @ValueSource(strings = {"0.00", "-10.00"})
    void split_totalNotPositive_throwsIllegalArgumentException(String total) {
        assertThrows(IllegalArgumentException.class,
                () -> splitter.split(new BigDecimal(total), 2));
    }
}

Cada prueba comprueba un solo comportamiento con la estructura preparar-actuar-comprobar, es independiente de las demás (el único estado compartido es el objeto bajo prueba, sin estado interno) y su nombre indica método, escenario y resultado esperado. Los casos de los límites (1 y 12 plazos, 0 y 13) y el invariante de que la suma de las cuotas es el total detectan los errores de redondeo típicos.

Jenkinsfile (pipeline declarativo, en la raíz del repositorio):

pipeline {
    agent { label 'maven-jdk21' }
    options {
        timeout(time: 30, unit: 'MINUTES')
        disableConcurrentBuilds()
    }
    stages {
        stage('Compilar y probar') {
            steps {
                sh 'mvn -B clean verify'
            }
            post {
                always {
                    junit 'target/surefire-reports/*.xml'
                }
            }
        }
        stage('Análisis SonarQube') {
            steps {
                withSonarQubeEnv('sonarqube-diputacion') {
                    sh 'mvn -B sonar:sonar'
                }
            }
        }
        stage('Quality Gate') {
            steps {
                timeout(time: 10, unit: 'MINUTES') {
                    waitForQualityGate abortPipeline: true
                }
            }
        }
        stage('Publicar en Nexus') {
            when {
                anyOf {
                    branch 'main'
                    branch pattern: 'release/.*', comparator: 'REGEXP'
                }
            }
            steps {
                withCredentials([usernamePassword(credentialsId: 'nexus-deploy',
                        usernameVariable: 'NEXUS_USER', passwordVariable: 'NEXUS_PASSWORD')]) {
                    sh 'mvn -B -s ci/settings.xml deploy -DskipTests'
                }
            }
        }
    }
}

Explicación. El Jenkinsfile está versionado con el código; se usa un job multibranch para que cada rama y Pull Request tenga su pipeline. La etapa de pruebas ejecuta mvn verify (compila y lanza las pruebas JUnit); si una falla, el build falla, y el paso junit publica los informes en Jenkins aunque haya fallos. withSonarQubeEnv toma la URL y el token del servidor SonarQube configurado en Jenkins con el nombre indicado (el token no está en el repositorio) y ejecuta el análisis con el plugin de Maven. waitForQualityGate espera el resultado del quality gate, que SonarQube comunica a Jenkins por un webhook configurado en SonarQube hacia la URL de Jenkins; con abortPipeline: true, si el quality gate no se supera el pipeline se aborta y no se publica nada, y el timeout evita esperar indefinidamente. La publicación en Nexus Repository solo ocurre en main y en las ramas release: mvn deploy sube el artefacto al repositorio definido en distributionManagement del pom (de versiones o de snapshots según la versión), y el usuario y la contraseña de Nexus salen de las credenciales de Jenkins (withCredentials) y llegan a Maven mediante el fichero ci/settings.xml, que solo referencia variables de entorno. Nunca se escriben contraseñas en el Jenkinsfile ni en el repositorio.
